CREATE TABLE public.withdrawals (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, leg TEXT NOT NULL, chain TEXT NOT NULL, asset TEXT NOT NULL, amount NUMERIC NOT NULL, from_address TEXT NOT NULL, to_address TEXT NOT NULL, txid TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'broadcast', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()); GRANT SELECT ON public.withdrawals TO authenticated; GRANT ALL ON public.withdrawals TO service_role; ALTER TABLE public.withdrawals ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users can read their own withdrawals" ON public.withdrawals FOR SELECT TO authenticated USING (auth.uid() = user_id);